public void AVAupdateInventItemCycleCount()
{
    AVAItemCycleCountOverviewLine       avaItemCycleCountOverviewLine;
    avaItemCycleCountOverviewObject     avaItemCycleCountOverviewObject;
    WHSWorkTable                        whsWorkTable;
    WHSWorkLine                         whsWorkLine;
    InventDim                           workLineInventDim;
    InventDim                           countLineInventDim = InventDim::find(this.InventDimId);
    AVAItemCycleCountStart              avaItemCycleCountStart;

    select firstonly  avaItemCycleCountOverviewLine
        where avaItemCycleCountOverviewLine.ItemId == this.ItemId
            && avaItemCycleCountOverviewLine.InventLocationId == countLineInventDim.InventLocationId
                join avaItemCycleCountOverviewObject
                    where avaItemCycleCountOverviewObject.ItemCycleCountOverviewLine == avaItemCycleCountOverviewLine.RecId
                            && avaItemCycleCountOverviewObject.ItemCycleCountObject       == AVAItemCycleCountObject::WorkTable
                    join whsWorkTable
                        where whsWorkTable.WorkId == avaItemCycleCountOverviewObject.ObjectId
                      join whsWorkLine
                        where whsWorkLine.WorkId == whsWorkTable.WorkId
                           && whsWorkLine.ItemId == this.ItemId
                                join workLineInventDim
                                    where workLineInventDim.inventDimId == whsWorkLine.InventDimId
                                       && workLineInventDim.wMSLocationId == countLineInventDim.wMSLocationId;
    if (whsWorkTable)
    {
        WHSWorkTable::cancelWork(whsWorkTable.workId) ; 
    }

